import 'package:buttons_tabbar/buttons_tabbar.dart';import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../Config/app_config.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Core/Utils/Widget/custom_sliver_grid_builder.dart';class ExploreScreen extends StatelessWidget {  const ExploreScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return [      SliverPadding(        padding: EdgeInsets.only(top: AppConfig.customPaddingFromTopBottom).r,        sliver: SliverFillRemaining(          fillOverscroll: false,          hasScrollBody: true,          child: DefaultTabController(            length: 6,            initialIndex: 0,            child: Column(              children: [                ButtonsTabBar(                  buttonMargin: EdgeInsets.symmetric(horizontal: 8.w),                  physics: AppConfig.physicsCustomScrollView,                  backgroundColor: AppColors.primaryColor,                  unselectedBackgroundColor: AppColors.backgroundColor,                  borderWidth: 1.w,                  borderColor: AppColors.grayscale30,                  unselectedBorderColor: AppColors.grayscale30,                  labelStyle: TextStyle(                    color: Colors.white,                    fontWeight: FontWeight.bold,                  ),                  unselectedLabelStyle: TextStyle(                    color: AppColors.grayscale60,                    fontWeight: FontWeight.bold,                  ),                  radius: 24.r,                  contentPadding: EdgeInsets.symmetric(                    horizontal: 22.5,                    vertical: 8,                  ).w,                  contentCenter: true,                  tabs: [                    ...List.generate(                      6,                      (index) => Tab(text: local.bed),                    )                  ],                  onTap: (p0) {},                ),                Expanded(                  child: Padding(                    padding: EdgeInsets.only(                            top: AppConfig.customPaddingFromTopBottom)                        .r,                    child: TabBarView(                      physics: NeverScrollableScrollPhysics(),                      children: [                        ...List.generate(                          6,                          (index) => BuildCustomGridBuilder(                            isSliver: false,                          ),                        ),                      ],                    ),                  ),                ),              ],            ),          ),        ),      ),    ].styledAppPages(withPadding: true, centered: true, withScroll: true);  }}